        audit.record("RATE_SET sheet=" + rate.getSheetId() + " by=" + AuditUser.decode(user)
                + " grade=" + rate.getGrade() + " rate=" + rate.getPct().setScale(2).toPlainString()
                + (rate.getFromDate() == null ? "" : " from=" + rate.getFromDate()));
    }
}
